# Head-to-head comparisons. Runs after all category files so their data and rankings exist.
# Prices and features from the category data, checked on the category's date.

compare_page(PM, "asana", "monday", "2026-10-26",
    ["You want unlimited automations on the first paid plan", "You run many cross-functional projects with goals and portfolios", "Your team likes structured lists and clear owners"],
    ["Many non-technical people need to adopt the tool quickly", "You prefer visual, colorful boards", "Lots of stakeholders only need to view work, not edit it"],
    "The two are close: Asana gives more automation and structure for the money, while monday.com is easier to roll out across a whole company.",
    "Annual billing, 10 users, from each vendor's list prices. Taxes and add-ons excluded.",
    [("Basic task and project management", "Starter ($10.99)", "$1,319", "Basic ($9)", "$1,080"),
     ("Plus timeline or Gantt view and automations", "Starter ($10.99)", "$1,319", "Standard ($12)", "$1,440"),
     ("Plus time tracking", "Advanced ($24.99)", "$2,999", "Pro ($19)", "$2,280"),
     ("Plus portfolios and resource management", "Advanced ($24.99)", "$2,999", "Enterprise (quote)", "Quote")],
    "monday.com paid plans start from 3 seats.",
    [("Free plan", "Personal, up to 2 users", "Free, up to 2 seats and 3 boards"),
     ("Entry paid plan", "Starter, $10.99/user/mo annual ($13.49 monthly)", "Basic, $9/seat/mo annual"),
     ("Timeline / Gantt view", "Listed from Starter", "Listed from Standard"),
     ("Automations", "Unlimited from Starter", "250 actions/mo on Standard, 25,000 on Pro"),
     ("Time tracking", "Listed from Advanced", "Listed from Pro"),
     ("Portfolios", "Listed from Advanced", "Portfolio management on Enterprise"),
     ("People who don't edit work", "Unlimited free guests from Starter", "Unlimited free viewers from Basic"),
     ("Trial", "Free plan", "14-day Pro trial")],
    [("Automation for the price.", "Starter includes unlimited automations; monday.com caps automation actions per month by plan."),
     ("Structure at scale.", "Goals, portfolios, approvals and resource management on Advanced suit organizations running many projects."),
     ("Timeline on the first paid plan.", "Timeline and Gantt views start on Starter.")],
    [("Adoption.", "Its visual boards and 200+ templates make it the easier tool to roll out to non-technical teams."),
     ("Cheaper entry seat.", "Basic is $9 per seat billed annually versus $10.99 for Asana Starter."),
     ("Time tracking sooner.", "Time tracking is on Pro ($19) rather than Asana Advanced ($24.99).")],
    ["List the views and automations you need on day one.", "Find the cheapest plan on each side that includes all of them; compare that price, not the entry price.", "Count who needs a paid seat versus who only views work.", "Run one real project in both for two weeks with the people who'll use it daily."],
    [("Is Asana or monday.com cheaper?", "monday.com's Basic seat is cheaper ($9 vs $10.99 billed annually), but Asana Starter includes timeline views and unlimited automations that need monday.com Standard ($12) or Pro ($19)."),
     ("Which has the better free plan?", "Both free plans cover 2 users. Asana's includes unlimited tasks and projects; monday.com's is limited to 3 boards."),
     ("Which is easier to use?", "monday.com is generally faster for non-technical teams to adopt; Asana rewards teams that want more structure."),
     ("Which is better for large organizations?", "Asana Advanced adds portfolios, goals and resource management at a published price; monday.com puts portfolio and resource management on Enterprise, priced by quote.")],
    desc="Asana vs monday.com: Asana Starter ($10.99) includes unlimited automations; monday.com Basic is $9 but caps automations. Prices, features and which to pick.")

compare_page(HD, "zendesk", "freshdesk", "2026-10-26",
    ["You need every channel, including voice, in one platform", "You want a large app marketplace and room to grow", "Budget allows for Suite plans"],
    ["You want a knowledge base and AI agent on the entry plan", "You need SLAs and routing without Zendesk Suite prices", "You're a growing team watching cost per agent"],
    "Both start at $19 per agent, but Freshdesk includes a knowledge base and an AI agent allowance on that entry plan, while Zendesk puts them on Suite Team at $55.",
    "Annual billing, 10 agents, from each vendor's list prices. AI resolutions beyond included amounts and add-ons excluded.",
    [("Email ticketing and automations", "Support Team ($19)", "$2,280", "Growth ($19)", "$2,280"),
     ("Plus knowledge base and an AI agent", "Suite Team ($55)", "$6,600", "Growth ($19)", "$2,280"),
     ("Plus advanced routing and custom reporting", "Suite Professional ($115)", "$13,800", "Pro ($55)", "$6,600")],
    "Zendesk includes 5 to 10 AI resolutions per agent per month and charges $1.50 to $2.00 for each extra; Freshdesk Growth includes 500 AI agent sessions.",
    [("Entry paid plan", "Support Team, $19/agent/mo annual ($25 monthly)", "Growth, $19/agent/mo annual"),
     ("Knowledge base", "Listed from Suite Team", "Listed from Growth"),
     ("AI agent", "From Suite Team; extra resolutions $1.50–$2.00", "500 sessions included from Growth"),
     ("AI copilot for agents", "Admin Copilot on Suite Professional", "$29/agent add-on"),
     ("Messaging, live chat and telephony", "Listed from Suite Team", "Not compared here"),
     ("Multiple SLA policies", "Not compared here", "Listed from Pro"),
     ("Free trial", "14 days", "14 days of Enterprise")],
    [("Channel coverage.", "Suite plans bring email, messaging, live chat and telephony into one platform with omnichannel routing."),
     ("Ecosystem.", "A large marketplace of apps and integrations."),
     ("Scale.", "Skills-based routing and IVR on Suite Professional suit larger support operations.")],
    [("More on the entry plan.", "Growth includes a knowledge base, customer portal and 500 AI agent sessions for $19 per agent."),
     ("Lower price for advanced features.", "Pro adds custom dashboards, intelligent routing and multiple SLA policies for $55, half of Zendesk Suite Professional."),
     ("Fewer add-ons to price.", "The AI agent allowance and knowledge base are part of the entry plan rather than a higher tier.")],
    ["List the channels you support today and in a year.", "Price the plan on each side that covers them, then add your expected AI resolution volume.", "Forward a week of real tickets into both trials and time how fast agents resolve them."],
    [("Is Freshdesk cheaper than Zendesk?", "At the entry level both are $19 per agent billed annually, but Freshdesk includes a knowledge base and AI agent allowance that need Zendesk Suite Team ($55)."),
     ("Which has better AI?", "Both include AI agents. Zendesk includes 5 to 10 automated resolutions per agent per month on Suite plans; Freshdesk Growth includes 500 AI agent sessions and sells Copilot as a $29 add-on."),
     ("Which is better for large teams?", "Zendesk's Suite plans offer broader channel coverage and routing for large, multichannel operations."),
     ("Do both have free trials?", "Yes, both offer 14-day trials.")],
    desc="Zendesk vs Freshdesk: both start at $19 per agent, but only Freshdesk includes a knowledge base and AI agent on that plan. Prices, features and the pick.")

compare_page(ACC, "quickbooks", "xero", "2026-10-26",
    ["Your accountant or bookkeeper works in QuickBooks", "You need inventory, project profitability and bill approvals on one plan", "You're a US business that wants a large app and advisor ecosystem"],
    ["Several people need access and you don't want per-user fees", "You want lower regular prices", "You're outside the US or work with an accountant who uses Xero"],
    "Xero is cheaper at every tier and has no per-user fees; QuickBooks is widely used by US accountants and puts inventory and projects together on Plus.",
    "Regular monthly prices × 12, before introductory discounts and taxes.",
    [("Entry plan", "Simple Start ($38), 1 user", "$456", "Early ($27), 20 invoices and 5 bills a month", "$324"),
     ("Unlimited invoicing and more users", "Essentials ($85), 3 users", "$1,020", "Growing ($59), no per-user fees", "$708"),
     ("Projects and growth features", "Plus ($140), 5 users, inventory and projects", "$1,680", "Established ($97), projects and multi-currency", "$1,164")],
    "Both vendors advertise steep introductory discounts for new customers; these are the prices after the promotions end.",
    [("Users", "1 (Simple Start), 3 (Essentials), 5 (Plus), 25 (Advanced)", "No per-user license fees on any plan"),
     ("Invoice and bill limits", "Not capped on the pricing page", "Early: 20 invoices and 5 bills a month; unlimited from Growing"),
     ("Inventory", "Listed from Plus", "Inventory Plus add-on on Growing and Established"),
     ("Project tracking", "Listed from Plus", "Listed from Established"),
     ("Multi-currency", "Not compared here", "Listed from Established"),
     ("Payroll", "Not compared here", "Xero Payroll powered by Gusto, $36/mo + $6 per person"),
     ("Free trial", "30-day trial", "Introductory offer for new customers")],
    [("Ecosystem.", "It is widely used by US accountants and bookkeepers and has a large app ecosystem."),
     ("Inventory and projects together.", "Plus combines inventory tracking and project profitability for up to 5 users."),
     ("Room to grow.", "Advanced supports up to 25 users with approval workflows.")],
    [("Lower prices.", "Each Xero tier costs less than the comparable QuickBooks plan at regular prices."),
     ("No per-user fees.", "You can give your whole team and your accountant access without paying per seat."),
     ("Higher user rating.", "Xero is rated 4.4/5 on G2 versus 4.0/5 for QuickBooks Online.")],
    ["Ask your accountant which they prefer; it saves time at every month end.", "Count invoices and bills per month to see whether Xero Early's caps fit.", "Count users who need access and compare the plan that covers them.", "Check that your bank feed connects in both before migrating."],
    [("Is Xero cheaper than QuickBooks?", "Yes, at regular prices: Xero Early is $27 a month versus $38 for QuickBooks Simple Start, and Xero Growing is $59 versus $85 for QuickBooks Essentials."),
     ("Which is better for a team with several users?", "Xero has no per-user fees on any plan, while QuickBooks limits users by plan (1, 3, 5 or 25)."),
     ("Which do accountants prefer?", "It depends on the accountant. QuickBooks is widely used in the US and Xero is widely used internationally, so ask yours before you choose."),
     ("Can I try both?", "QuickBooks offers a 30-day trial, and Xero runs introductory offers for new customers.")],
    desc="QuickBooks vs Xero at regular prices: $38 vs $27 entry plans, user limits vs no per-user fees, and which to pick for your business and accountant.")

# Sales comparisons. Apollo.io plan prices and credits from apollo.io/pricing, ZoomInfo editions from zoominfo.com/pricing,
# Gong and Avoma from their pricing pages, Aircall and JustCall from their pricing pages; all checked Oct 26, 2026.

compare_page(DATA, "apollo", "zoominfo", "2026-10-26",
    ["You want to see the price before you talk to sales", "You need data and email sequences in one subscription", "You're a startup or small team that may start on the free plan"],
    ["You run account-based selling across large territories", "You want buyer intent, website visitor and champion tracking signals", "You can negotiate an annual contract and want one vendor for sales and marketing data"],
    "Apollo.io publishes its prices and bundles outreach with the data; ZoomInfo sells by quote and goes deeper on intent and account signals for larger go-to-market teams.",
    "Annual billing, 10 seats, from Apollo.io's list prices. ZoomInfo doesn't publish prices, so its column shows the edition that matches each need.",
    [("Contact data and email sequences", "Basic ($49)", "$5,880", "Professional", "Quote"),
     ("More credits, AI features and call recording", "Professional ($79)", "$9,480", "Professional", "Quote"),
     ("Buyer intent and account signals", "Organization ($119), 12 intent topics", "$14,280", "Copilot Advanced", "Quote")],
    "Apollo.io Organization requires at least 3 seats. ZoomInfo prices by features, number of licenses and credit usage; get a written quote for the same seat count before comparing.",
    [("Published pricing", "$49, $79 and $119 per seat per month, billed annually", "No; quote based on features, licenses and credits"),
     ("Free plan", "Yes, 900 credits per seat per year", "No; free trial of the sales plans"),
     ("Credits per seat", "30,000 a year on Basic, 48,000 on Professional, 72,000 on Organization", "A set number of monthly credits per package"),
     ("What a credit buys", "Email 1 credit, phone number 8 credits", "Each export of a contact or company profile costs 1 credit"),
     ("Email sequences", "Unlimited from Basic (2 per team on Free)", "AI email generation listed on Professional"),
     ("Dialer", "Listed from Basic", "Not listed in the sales plans"),
     ("Buyer intent", "1 intent topic on Free, 6 on Basic and Professional, 12 on Organization", "Intent signals from Copilot Advanced; custom and real-time intent on Copilot Enterprise"),
     ("API access", "On Custom plans", "Not compared here")],
    [("Price you can see.", "Every self-serve plan has a published per-seat price, and credits are granted upfront at the start of each billing cycle."),
     ("Data and outreach in one tool.", "Sequences, a dialer and a meeting scheduler come with the paid plans, so a small team doesn't need a separate engagement tool."),
     ("A free way in.", "The free plan stays free with no time limit, and the trial includes 75 credits.")],
    [("Account signals.", "Copilot Advanced adds account fit scoring, buyer intent, website visitors and champion tracking."),
     ("Enterprise depth.", "Copilot Enterprise adds real-time and custom intent signals, advanced reporting and a dedicated customer service manager."),
     ("Breadth of data products.", "One vendor covers sales, marketing and talent data, with integrations for CRM and marketing tools.")],
    ["Estimate how many emails and phone numbers each rep needs per month; phone numbers cost 8 Apollo.io credits each.", "Get a written ZoomInfo quote for the same seat count and credit volume.", "Pull the same 100 target accounts in both trials and compare match rates and phone accuracy.", "Decide whether you also need sequencing; if you do, add your engagement tool's cost to the ZoomInfo quote."],
    [("Is Apollo.io cheaper than ZoomInfo?", "Apollo.io publishes prices from $49 per seat per month billed annually and has a free plan. ZoomInfo doesn't publish prices, so compare Apollo.io's plan against a written ZoomInfo quote for the same seats and credits."),
     ("Is ZoomInfo data better than Apollo.io?", "ZoomInfo is built for enterprise go-to-market teams and adds intent and account signals on its Copilot editions. Data quality varies by region and segment, so test both on your own target accounts."),
     ("Does Apollo.io have a free plan?", "Yes. The free plan includes 900 credits per seat per year and 2 sequences per team, with no time limit."),
     ("Can I use Apollo.io and ZoomInfo together?", "Yes, some teams use ZoomInfo for account data and intent and Apollo.io for sequencing, but you pay for two data subscriptions.")],
    desc="Apollo.io vs ZoomInfo: Apollo.io publishes prices from $49 per seat with a free plan; ZoomInfo sells by quote with deeper intent data. Credits, features and the pick.")

compare_page(CI, "gong", "avoma", "2026-10-26",
    ["You're a mid-market or enterprise sales org with a RevOps team", "You want coaching, deal inspection and forecasting on one platform", "Budget allows for an annual contract with a platform fee"],
    ["You want published prices and a free trial", "Only some of your team records calls and the rest just view them", "You want call scoring and deal risk without an enterprise contract"],
    "Gong is the deeper platform for large revenue teams; Avoma covers call scoring and deal risk through published add-ons, without an enterprise contract.",
    "Annual billing, 10 recording seats, from Avoma's list prices. Gong doesn't publish prices, so its column shows a quote.",
    [("Recording, transcripts and notes saved to CRM", "Quote", "Quote", "Startup ($19)", "$2,280"),
     ("Plus AI call scoring and coaching", "Quote", "Quote", "Startup + Conversation Intelligence ($48)", "$5,760"),
     ("Plus deal risk and forecasting", "Quote", "Quote", "Startup + Conversation and Revenue Intelligence ($77)", "$9,240")],
    "Gong prices licenses per user and adds a platform fee that depends on the number of users. Avoma's Startup plan allows up to 25 paid seats; viewers and collaborators are free.",
    [("Published pricing", "No; per-user licenses plus a platform fee", "Yes: Startup $19, Enterprise $39 per seat per month billed annually"),
     ("Who needs a paid seat", "Priced per user", "Only people who record meetings; viewers are free"),
     ("Call scoring and coaching", "Core of the platform", "Conversation Intelligence add-on, $29 per seat: AI call scoring, custom scorecards such as SPICED and MEDDICC"),
     ("Deal risk and forecasting", "Gong Forecast", "Revenue Intelligence add-on, $29 per seat: deal risk alerts, deal health score, forecasting"),
     ("Integrations", "Integrations with your existing stack are free", "Notes save to CRM records on Startup; native CRM integrations listed with Revenue Intelligence"),
     ("Free trial", "No free trial listed", "14 days with all add-ons, no card needed")],
    [("Depth.", "Coaching, deal inspection and pipeline insight are the core of the product rather than add-ons."),
     ("One platform.", "Engagement, forecasting and enablement products run on the same conversation data."),
     ("Free integrations.", "Its pricing page says connecting your existing tools costs nothing extra.")],
    [("Transparent cost.", "Every plan and add-on has a published price, so you can budget without a sales cycle."),
     ("Pay only for recorders.", "Viewers and collaborators are free, which keeps the bill down for managers and cross-functional teams."),
     ("Try before you buy.", "A 14-day trial includes every add-on and needs no card.")],
    ["Count how many people record calls versus only review them.", "List the features you need on day one: notes, scoring, deal risk or forecasting.", "Price Avoma with only the add-ons you need, then ask Gong for a quote at the same seat count.", "Run Avoma's trial on a week of real calls and ask Gong for a pilot or reference customers your size."],
    [("Is Avoma cheaper than Gong?", "Avoma publishes prices from $19 per seat per month billed annually, with call scoring and deal intelligence as $29 add-ons. Gong doesn't publish prices and charges a platform fee on top of per-user licenses, so get a quote to compare."),
     ("Does Gong have a free trial?", "Gong's pricing page doesn't list a free trial; it builds a custom proposal. Avoma offers a 14-day trial with all add-ons and no card."),
     ("Is Avoma a good Gong alternative?", "For growing teams, yes: it covers AI call scoring, deal risk alerts and forecasting at published prices. Gong goes deeper for large revenue orgs that want engagement, forecasting and enablement on one platform."),
     ("Do viewers need a paid seat?", "Not on Avoma, where viewers and collaborators are free. Gong prices licenses per user.")],
    desc="Gong vs Avoma: Gong sells by quote with a platform fee; Avoma starts at $19 per seat with $29 add-ons for call scoring and deal risk. Costs, features and the pick.")

compare_page(DIAL, "aircall", "justcall", "2026-10-26",
    ["You need a reliable phone system for inbound and outbound calls first", "Your reps call mostly within the US and Canada and want unlimited outbound minutes there", "You want a simple rollout and a large integration marketplace"],
    ["You want predictive dialing as your team grows", "You want AI call scoring and real-time assist included in a plan", "You have a 2-person team (Aircall's minimum is 3 licenses)"],
    "Their power dialer plans cost almost the same; Aircall is the simpler phone system, while JustCall offers more dialing modes and includes AI coaching on a plan instead of an add-on.",
    "Annual billing, 10 users, from each vendor's list prices. Taxes, extra numbers and usage add-ons excluded.",
    [("Business phone, no dialer", "Essentials ($30)", "$3,600", "Team ($29)", "$3,480"),
     ("Plus a power dialer and Salesforce integration", "Professional ($50)", "$6,000", "Pro ($49)", "$5,880"),
     ("Plus AI call scoring and coaching", "Professional + AI Assist Pro ($99)", "$11,880", "Pro Plus ($89)", "$10,680"),
     ("Predictive dialing", "Not listed", "Not listed", "SalesPro (quote)", "Quote")],
    "Aircall requires at least 3 licenses and charges $6 a month for each extra number. JustCall requires at least 2 users.",
    [("Entry plan", "Essentials, $30 per license billed annually", "Team, $29 per user billed annually"),
     ("Power dialer", "Listed from Professional", "Listed from Pro"),
     ("Predictive dialer", "Not listed", "SalesPro (quote), up to 10 lines"),
     ("Salesforce integration", "Listed from Professional", "Salesforce CTI listed from Pro"),
     ("AI features", "Call transcription from Essentials; AI summaries from Professional; AI Assist Pro $49 per seat add-on", "AI call scoring and real-time agent assist on Pro Plus"),
     ("Calling allowance", "Unlimited inbound, internal and US and Canada outbound from Essentials", "Unlimited inbound; 1,000 outbound minutes per user in the US and Canada"),
     ("Minimum", "3 licenses", "2 users"),
     ("Trial", "Free access offer", "14 days, no card, includes SalesPro features")],
    [("Phone system first.", "Easy setup for inbound and outbound teams, with IVR, call queues and recording from the entry plan."),
     ("Unlimited calling.", "Essentials and Professional include unlimited US and Canada outbound calls."),
     ("Integrations.", "A large marketplace, with HubSpot listed from Essentials and Salesforce from Professional.")],
    [("More dialing modes.", "Power dialing on Pro and predictive dialing on up to 10 lines with SalesPro."),
     ("AI coaching in the plan.", "Pro Plus includes AI call scoring and real-time agent assist for $89, less than Aircall Professional plus AI Assist Pro."),
     ("Smaller teams.", "Plans start at 2 users, and the 14-day trial needs no card.")],
    ["Decide whether you need a phone system, a power dialer or predictive dialing.", "Estimate outbound minutes per rep; JustCall lists 1,000 per user in the US and Canada.", "Price the plan on each side that includes your dialer and AI needs.", "Run a week of real calls in both trials and compare connect rates and CRM logging."],
    [("Is JustCall cheaper than Aircall?", "Slightly, at each comparable tier: $29 vs $30 for the entry plan and $49 vs $50 for the power dialer plan, billed annually. With AI coaching, JustCall Pro Plus ($89) costs less than Aircall Professional plus AI Assist Pro ($99)."),
     ("Which has a power dialer?", "Both, on their second plan: Aircall Professional and JustCall Pro. Neither includes it on the entry plan."),
     ("Does Aircall have a predictive dialer?", "Aircall's pricing page lists a Power Dialer, not a predictive dialer. JustCall offers predictive dialing on its quote-based SalesPro plan."),
     ("Do both offer free trials?", "JustCall offers a 14-day trial with no card needed. Aircall offers free access to test the platform; its pricing page doesn't state the length.")],
    desc="Aircall vs JustCall: power dialer plans at $50 vs $49 per user, AI coaching as an add-on vs in the plan, and which suits your sales team. Prices compared.")
